const lv_image_dsc_t *emoji_face(const char *emotion)
{
    if (emotion && emotion[0])
        for (size_t i = 0; i < sizeof FACES / sizeof FACES[0]; i++)
            if (!strcmp(FACES[i].name, emotion)) return FACES[i].img;
    return &neutral_img;
}
